function cleanPersian(text) {
	if (language !== 'fa') return text;
	return String(text).replace(/سوئد/g, '\uE000')
		.replace(/[\u064b-\u065f\u0670]/g, '').replace(/[أإٱ]/g, 'ا').replace(/ؤ/g, 'و').replace(/ئ/g, 'ی').replace(/ء/g, '')
		.replace(/\uE000/g, 'سوئد').replace(/Psiphon/gi, 'سایفون').replace(/تور/g, 'TOR').replace(/\bTor\b/g, 'TOR')
		.replace(/دکمه اصلی/g, 'کلید اصلی').replace(/حل[‌ ]کننده/g, 'ریزالور').replace(/قطعه[‌ ]بندی TLS/g, 'فرگمنت TLS').replace(/اندازه قطعه[‌ ]های TLS/g, 'اندازه فرگمنت TLS').replace(/فاصله قطعه[‌ ]های TLS/g, 'فاصله فرگمنت‌های TLS');
}

return baseclass.extend({
	clean: cleanPersian,
	get: function() { return language; },
	dir: function() { return language === 'fa' ? 'rtl' : 'ltr'; },
	locale: function() { return { fa: 'fa-IR', en: 'en-US', ru: 'ru-RU', zh: 'zh-CN' }[language]; },
	tr: function(text) {
		return language === 'fa' ? cleanPersian(text) : (messages[text] || [text, text, text])[{ en: 0, ru: 1, zh: 2 }[language]];
	},
	selector: function() {
		var select = E('select', { 'class': 'ae-language', 'aria-label': this.tr('زبان') },
			[['fa', 'فارسی'], ['en', 'English'], ['ru', 'Русский'], ['zh', '简体中文']].map(function(item) {
				return E('option', { 'value': item[0] }, item[1]);
			}));
		select.value = language;
		select.addEventListener('change', function() {
			try { window.localStorage.setItem('gozarbin-language', select.value); } catch (e) { return; }
			window.location.reload();
		});
		return select;
	}
});
